/**
 * Calculate late fee for an overdue invoice: 0.04% per day of the amount still due.
 * @param {object} invoice
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {number} - Late fee in cents, or 0 if not overdue
 */
export function lateFee(invoice, asOf) {
  if (invoice.dueDate >= asOf) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const due = balanceDue(invoice);
  const fee = due * 0.0004 * daysOverdue;
  return roundCents(fee);
}

/**
 * Get a dashboard summary of invoices.
 * @param {Array<object>} invoices
 * @param {string} asOf - Date in YYYY-MM-DD format
 * @returns {{ counts: { draft: number, issued: number, partially_paid: number, paid: number }, outstanding: number, overdue: { count: number, amount: number }, topCustomers: Array<{ customerId: string, due: number }> }}
 */
export function dashboard(invoices, asOf) {
  const counts = {
    draft: 0,
    issued: 0,
    partially_paid: 0,
    paid: 0,
  };

  for (const invoice of invoices) {
    counts[invoice.status]++;
  }

  let outstanding = 0;
  for (const invoice of invoices) {
    if (invoice.status === 'issued' || invoice.status === 'partially_paid') {
      outstanding += balanceDue(invoice);
    }
  }

  const overdueList = overdueInvoices(invoices, asOf);
  const overdue = {
    count: overdueList.length,
    amount: overdueList.reduce((sum, inv) => sum + inv.due, 0),
  };

  const customerDues = new Map();
  for (const invoice of invoices) {
    if (invoice.status === 'issued' || invoice.status === 'partially_paid') {
      const due = balanceDue(invoice);
      if (!customerDues.has(invoice.customerId)) {
        customerDues.set(invoice.customerId, 0);
      }
      customerDues.set(invoice.customerId, customerDues.get(invoice.customerId) + due);
    }
  }

  const topCustomers = Array.from(customerDues.entries())
    .map(([customerId, due]) => ({ customerId, due }))
    .sort((a, b) => b.due - a.due)
    .slice(0, 3);

  return {
    counts,
    outstanding,
    overdue,
    topCustomers,
  };
}

