test('vatSummary: calculates base correctly (qty * unitPrice - discount)', () => {
  const invoices = [
    {
      status: 'issued',
      lines: [{ qty: 2, unitPrice: 5000, discountPercent: 10, vatRate: 21 }],
    },
  ];
  const result = vatSummary(invoices);
  assert.equal(result.length, 1);
  // total = 2 * 5000 = 10000, discount = 10000 * 0.1 = 1000, base = 9000
